import React, { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { Web3Context } from '../contexts/Web3Context';

const Marketplace = () => {
  const [exercises, setExercises] = useState([]);
  const { currentAccount } = useContext(Web3Context);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    axios.get('http://localhost:5000/api/exercises')
      .then(res => setExercises(res.data))
      .catch(err => console.error(err));
  }, []);

  const submitAnswer = async (exId, selectedIdx, cardIndex) => {
    if (!currentAccount) return alert("Vui lòng kết nối ví!");
    
    // UI Loading cục bộ (chỉ card đang chọn)
    const newExs = [...exercises];
    newExs[cardIndex].processing = true;
    setExercises(newExs);

    try {
      const res = await axios.post('http://localhost:5000/api/submit-answer', {
        exercise_id: exId,
        learner_address: currentAccount,
        selected_option_index: selectedIdx
      });

      // Cập nhật kết quả vào Card
      newExs[cardIndex].result = res.data;
    } catch (err) {
      alert("Lỗi giao dịch");
    } finally {
      newExs[cardIndex].processing = false;
      setExercises([...newExs]);
    }
  };

  return (
    <div className="max-w-6xl mx-auto p-6">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-gray-800 mb-2">🏆 Learn-to-Earn Arena</h1>
        <p className="text-gray-500">Thử thách kiến thức - Nhận thưởng Token thật</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {exercises.map((ex, index) => (
          <div key={ex._id} className="glass-panel rounded-xl overflow-hidden hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 relative">
            
            {/* Badge Chủ đề */}
            <div className="bg-gradient-to-r from-blue-500 to-purple-600 text-white text-xs font-bold px-3 py-1 absolute top-3 right-3 rounded-full">
              {ex.topic}
            </div>

            <div className="p-6">
              <div className="flex items-center gap-2 mb-4">
                <div className="w-8 h-8 rounded-full bg-gray-200 flex items-center justify-center text-xs font-bold">
                  {ex.creator_address.slice(2, 4)}
                </div>
                <div className="text-xs text-gray-500">
                  <p>Creator</p>
                  <p className="font-mono font-bold text-gray-700">{ex.creator_address.slice(0,6)}...{ex.creator_address.slice(-4)}</p>
                </div>
              </div>

              <h3 className="text-lg font-bold text-gray-800 mb-6 min-h-[60px]">{ex.question_content}</h3>

              <div className="space-y-2">
                {ex.options.map((opt, idx) => (
                  <button
                    key={idx}
                    disabled={!!ex.result || ex.processing}
                    onClick={() => submitAnswer(ex._id, idx, index)}
                    className={`w-full text-left px-4 py-3 rounded-lg text-sm border transition-all ${
                      ex.result 
                        ? (ex.result.is_correct && idx === ex.result.correctIndex ? 'bg-green-100 border-green-500 text-green-800' 
                          : (!ex.result.is_correct && idx === ex.result.selectedIndex ? 'bg-red-100 border-red-500 text-red-800' : 'bg-gray-50 opacity-50'))
                        : 'border-gray-200 hover:border-blue-500 hover:bg-blue-50'
                    }`}
                  >
                    <span className="font-bold mr-2">{['A','B','C','D'][idx]}.</span> {opt}
                  </button>
                ))}
              </div>
            </div>

            {/* Footer Stake Info */}
            <div className="bg-gray-50 px-6 py-3 border-t flex justify-between items-center text-sm">
              <div className="flex items-center text-red-500 font-bold">
                🔥 Cược: {ex.stake_amount}
              </div>
              <div className="flex items-center text-green-600 font-bold">
                🎁 Thưởng: 10
              </div>
            </div>

            {/* Loading Overlay */}
            {ex.processing && (
              <div className="absolute inset-0 bg-white/80 flex items-center justify-center z-10">
                <div className="animate-spin text-3xl">⚙️</div>
              </div>
            )}

            {/* Result Overlay */}
            {ex.result && (
              <div className={`absolute inset-0 flex items-center justify-center z-10 bg-opacity-90 ${ex.result.is_correct ? 'bg-green-500' : 'bg-red-500'} text-white text-center p-4`}>
                <div>
                  <div className="text-5xl mb-2">{ex.result.is_correct ? '🎉' : '💸'}</div>
                  <h3 className="text-2xl font-bold">{ex.result.is_correct ? 'CHÍNH XÁC!' : 'SAI RỒI!'}</h3>
                  <p className="mt-2 text-white/90">{ex.result.message}</p>
                  {ex.result.tx_hash && (
                    <a href={`https://sepolia.etherscan.io/tx/${ex.result.tx_hash}`} target="_blank" className="underline text-sm mt-2 block text-white/80">Xem giao dịch</a>
                  )}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default Marketplace;
